// Valida o payload recebido do agenda-booking / agenda-n8n-receiver
const body = $input.first().json.body ?? $input.first().json;

const event      = body.event;           // 'created' | 'confirmed' | 'cancelled' | 'reminder'
const clientId   = body.client_id;
const apptId     = body.appointment_id;

if (!event || !clientId) {
  throw new Error('Payload inválido: event e client_id são obrigatórios');
}

// Se os dados do cliente final já vieram no payload, usa direto
// Caso contrário, serão buscados no próximo node
return [{
  json: {
    event,
    client_id:      clientId,
    appointment_id: apptId ?? null,
    customer_email: body.customer_email  ?? null,
    customer_name:  body.customer_name   ?? null,
    service_name:   body.service_name    ?? null,
    start_at:       body.start_at        ?? null,
    end_at:         body.end_at          ?? null,
    needs_lookup:   !body.customer_email || !body.start_at,
  }
}];

// Mescla dados buscados com payload original
const appt = $input.first().json[0] ?? $input.first().json;
const orig = $('Parsear Payload').first().json;

return [{
  json: {
    event:          orig.event,
    client_id:      appt.client_id ?? orig.client_id,
    appointment_id: appt.id        ?? orig.appointment_id,
    customer_email: appt.customer_email ?? orig.customer_email,
    customer_name:  appt.customer_name  ?? orig.customer_name,
    service_name:   appt.service_name   ?? orig.service_name,
    start_at:       appt.start_at       ?? orig.start_at,
    end_at:         appt.end_at         ?? orig.end_at,
  }
}];

// Log do resultado
const result = $input.first().json;
if (result.skipped) {
  console.log(`E-mail pulado: ${result.reason}`);
} else if (result.success) {
  console.log(`E-mail enviado: ${result.resend_id}`);
} else {
  console.error(`Erro ao enviar e-mail: ${result.error}`);
}
return $input.all();
